create table if not exists public.cash_register_history(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,cash_register_id uuid,opened_at timestamptz not null,closed_at timestamptz not null,opening_amount numeric not null default 0,closing_amount numeric not null default 0,opened_by uuid references auth.users(id) on delete set null,closed_by uuid references auth.users(id) on delete set null,summary jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index if not exists cash_register_history_company_closed_idx on public.cash_register_history(company_id,closed_at desc);alter table public.cash_register_history enable row level security;drop policy if exists cash_register_history_tenant_select on public.cash_register_history;create policy cash_register_history_tenant_select on public.cash_register_history for select to authenticated using(company_id=public.current_user_company_id());revoke all on public.cash_register_history from anon;grant select on public.cash_register_history to authenticated;

create or replace function public.open_cash_register_authorized(p_opening_amount numeric default 0) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare v_uid uuid:=auth.uid();v_company uuid;v_role text;v_permissions jsonb;v_active boolean;v_allowed boolean;v_row public.cash_registers%rowtype;
begin if v_uid is null then raise exception 'Usuario no autenticado';end if;select company_id,role,permissions,active into v_company,v_role,v_permissions,v_active from public.profiles where id=v_uid;v_allowed:=coalesce(v_active,false) and(v_role='owner' or coalesce((v_permissions->>'can_open_close_cash')::boolean,v_role in('cashier','manager','supervisor'),false));if v_company is null or not v_allowed then raise exception 'Tu usuario no tiene permiso para abrir la caja';end if;select * into v_row from public.cash_registers where company_id=v_company and status='open' limit 1;if found then raise exception 'Ya hay una caja abierta para este comercio';end if;select * into v_row from public.cash_registers where company_id=v_company order by opened_at desc nulls last limit 1 for update;if found then update public.cash_registers set status='open',opening_amount=greatest(0,coalesce(p_opening_amount,0)),closing_amount=null,opened_at=now(),closed_at=null,opened_by=v_uid,closed_by=null,close_summary='{}'::jsonb where id=v_row.id returning * into v_row;else insert into public.cash_registers(company_id,name,status,opening_amount,opened_at,opened_by,close_summary) values(v_company,'Caja principal','open',greatest(0,coalesce(p_opening_amount,0)),now(),v_uid,'{}'::jsonb) returning * into v_row;end if;return to_jsonb(v_row);end;$$;

create or replace function public.close_cash_register_authorized(p_register_id uuid,p_closing_amount numeric default null) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare v_uid uuid:=auth.uid();v_company uuid;v_role text;v_permissions jsonb;v_active boolean;v_allowed boolean;v_row public.cash_registers%rowtype;v_now timestamptz:=now();v_sales_total numeric:=0;v_sales_count integer:=0;v_cash_sales numeric:=0;v_income numeric:=0;v_expense numeric:=0;v_egress numeric:=0;v_expected numeric:=0;v_closing numeric;v_payments jsonb:='{}'::jsonb;v_summary jsonb;v_history uuid;
begin if v_uid is null then raise exception 'Usuario no autenticado';end if;select company_id,role,permissions,active into v_company,v_role,v_permissions,v_active from public.profiles where id=v_uid;v_allowed:=coalesce(v_active,false) and(v_role='owner' or coalesce((v_permissions->>'can_open_close_cash')::boolean,v_role in('cashier','manager','supervisor'),false));if v_company is null or not v_allowed then raise exception 'Tu usuario no tiene permiso para cerrar la caja';end if;select * into v_row from public.cash_registers where id=p_register_id and company_id=v_company and status='open' for update;if not found then raise exception 'La caja ya está cerrada o no pertenece a este comercio';end if;
select coalesce(sum(total),0),count(*) into v_sales_total,v_sales_count from public.sales where company_id=v_company and sold_at>=v_row.opened_at and sold_at<=v_now;select coalesce(sum(total),0) into v_cash_sales from public.sales where company_id=v_company and sold_at>=v_row.opened_at and sold_at<=v_now and lower(coalesce(payment_method,'')) like '%efect%';select coalesce(jsonb_object_agg(payment_method,total),'{}'::jsonb) into v_payments from(select coalesce(nullif(payment_method,''),'Sin informar') payment_method,round(sum(total)::numeric,2) total from public.sales where company_id=v_company and sold_at>=v_row.opened_at and sold_at<=v_now group by 1)q;select coalesce(sum(amount) filter(where kind='income'),0),coalesce(sum(amount) filter(where kind='expense'),0),coalesce(sum(amount) filter(where kind='egress'),0) into v_income,v_expense,v_egress from public.cash_movements where company_id=v_company and occurred_at>=v_row.opened_at and occurred_at<=v_now;v_expected:=coalesce(v_row.opening_amount,0)+v_cash_sales+v_income-v_expense-v_egress;v_closing:=coalesce(p_closing_amount,v_expected);v_summary:=jsonb_build_object('sales_total',round(v_sales_total,2),'sales_count',v_sales_count,'payments',v_payments,'cash_sales',round(v_cash_sales,2),'income',round(v_income,2),'expenses',round(v_expense,2),'egress',round(v_egress,2),'expected_cash',round(v_expected,2),'counted_cash',round(v_closing,2),'difference',round(v_closing-v_expected,2),'opening_amount',coalesce(v_row.opening_amount,0),'opened_at',v_row.opened_at,'closed_at',v_now);insert into public.cash_register_history(company_id,cash_register_id,opened_at,closed_at,opening_amount,closing_amount,opened_by,closed_by,summary) values(v_company,v_row.id,v_row.opened_at,v_now,coalesce(v_row.opening_amount,0),v_closing,v_row.opened_by,v_uid,v_summary) returning id into v_history;update public.cash_registers set status='closed',closed_at=v_now,closed_by=v_uid,closing_amount=v_closing,close_summary=v_summary where id=v_row.id returning * into v_row;return to_jsonb(v_row)||jsonb_build_object('history_id',v_history);end;$$;
revoke all on function public.open_cash_register_authorized(numeric) from public,anon;revoke all on function public.close_cash_register_authorized(uuid,numeric) from public,anon;grant execute on function public.open_cash_register_authorized(numeric) to authenticated,service_role;grant execute on function public.close_cash_register_authorized(uuid,numeric) to authenticated,service_role;
